// Убирает обёртку-кортеж, чтобы проверяемый тип T был голым и дистрибутировал по объединению.

scenario.en:
function unwrap<T>(x: T): T extends Promise<infer U> ? U : T { throw 0 }
const a = unwrap(Promise.resolve('hi'));
const b = unwrap(42);
What are the types of a and b?

